from typing import List

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        cnt = 0
        i = len(nums) - 1

        while i >= 0:
            j = abs(nums[i]) - 1
            if j < k:
                if nums[i] > 0:
                    cnt += 1
                    nums[i] *= -1
                    if cnt == k:
                        return len(nums) - i
            i -= 1

        return 0

